def reference(x):
    """CPU FP64 evaluation followed by FP16 conversion, returned on x.device."""
    validate_inputs(x, require_cuda=False)
    values = x.detach().to(device="cpu", dtype=torch.float64)
    result = torch.sigmoid(values).to(torch.float16)
    return result.to(x.device)
